package com.bank.orders.service;

import com.bank.orders.model.Order;
import com.bank.orders.repository.OrderRepository;

import java.util.*;
import java.util.stream.Collectors;

public class OrderAnalyticsService {
    private final OrderRepository repo;
    public OrderAnalyticsService(OrderRepository repo) { this.repo = repo; }

    private Map<String, List<Order>> partitionByCustomer() {
        return repo.findAll().stream().collect(Collectors.groupingBy(Order::getCustomerId));
    }

    // ROW_NUMBER() OVER (PARTITION BY customer ORDER BY created_at DESC, id DESC) = 1
    public List<Order> latestPerCustomer() {
        List<Order> result = new ArrayList<>();
        partitionByCustomer().forEach((cust, orders) -> orders.stream()
            .sorted(Comparator.comparing(Order::getCreatedAt).thenComparing(Order::getId).reversed())
            .limit(1).forEach(result::add));                 // rn = 1
        return result;
    }

    // ORDER BY total_amount DESC, id DESC  rn = 1
    public List<Order> mostExpensivePerCustomer() {
        List<Order> result = new ArrayList<>();
        partitionByCustomer().forEach((cust, orders) -> orders.stream()
            .sorted(Comparator.comparing(Order::getTotalAmount).thenComparing(Order::getId).reversed())
            .limit(1).forEach(result::add));                 // rn = 1
        return result;
    }

    // ORDER BY total_amount DESC, id DESC  rn <= 3
    public List<Order> topThreeByAmountPerCustomer() {
        List<Order> result = new ArrayList<>();
        partitionByCustomer().forEach((cust, orders) -> orders.stream()
            .sorted(Comparator.comparing(Order::getTotalAmount).thenComparing(Order::getId).reversed())
            .limit(3).forEach(result::add));                 // rn <= 3
        return result;
    }
}
